// Hand-written. Not generated by Speakeasy.
//
// Three settings were taken off authlete_service before 3.0.0, because taking
// an attribute away afterwards is a major version.
//
// Two are Authlete 2.x social login for the developer console, deprecated in
// the 3.0 server, so a practitioner could write one, watch the apply succeed,
// and never learn it did nothing. They are removed in the overlay with
// x-speakeasy-terraform-ignore.
//
// The third, server_url, is worse than redundant. Setting it passes
// operations.WithServerURL, so the request goes straight to that URL, the
// origin never matches the one idpRoutingTransport watches for, and the
// transport neither redirects it nor injects organizationId and apiServerId. A
// self-managed deployment then fails with an IdP error naming neither cause.
// It has no schema node, so it is removed by a script instead.
//
// Either mechanism can be lost silently: an overlay entry can be dropped by an
// edit, and the script's edit is undone by every regeneration. The provider
// builds and passes its other tests with any of the three back.
package provider

import "testing"

func TestRemovedServiceAttributesStayRemoved(t *testing.T) {
	attrs := resourceSchema(t, NewServiceResource()).Attributes

	for name, why := range map[string]string{
		"developer_sns_credentials": "Authlete 2.x social login, deprecated in the 3.0 server.\n\n" +
			"Restore x-speakeasy-terraform-ignore on " +
			"$.components.schemas.service.properties.developerSnsCredentials " +
			"in .speakeasy/terraform_overlay.yaml and regenerate.",
		"supported_developer_snses": "Authlete 2.x social login, deprecated in the 3.0 server.\n\n" +
			"Restore x-speakeasy-terraform-ignore on " +
			"$.components.schemas.service.properties.supportedDeveloperSnses " +
			"in .speakeasy/terraform_overlay.yaml and regenerate.",
		"server_url": "Setting this sends service create and delete straight to that " +
			"URL, so idp_routing.go never recognises the origin and never injects " +
			"organizationId or apiServerId.\n\n" +
			"A regeneration has most likely restored it. Run:\n\n" +
			"  python3 scripts/patch-resource-server-url.py",
	} {
		if _, present := attrs[name]; present {
			t.Errorf("authlete_service has a `%s` attribute again.\n\n%s", name, why)
		}
	}
}

// The counterpart, and the more valuable of the two.
//
// id_token_dropped_on_issue_without_openid was removed alongside the others on
// a report that the server disregarded it, and put back when that was
// measured and found false: true -> false -> true persists and reads back.
//
// It stays because of an asymmetry the pre-GA deadline obscures. Putting an
// attribute back is not a breaking change; taking one away is. So an
// unverified removal is the expensive mistake and an unverified keep is the
// cheap one. Anything removed from this resource should have been measured,
// not inferred, and this test is where that is recorded.
func TestTheIDTokenSettingStaysUntilItIsMeasured(t *testing.T) {
	attrs := resourceSchema(t, NewServiceResource()).Attributes
	if _, present := attrs["id_token_dropped_on_issue_without_openid"]; !present {
		t.Error("id_token_dropped_on_issue_without_openid has been removed again.\n\n" +
			"It was removed once on an unverified report and restored when the " +
			"live API showed the value persisting across updates.\n\n" +
			"Whether the token flow honours the flag is a separate question, and " +
			"not one the provider answers: its job is to set and read a documented " +
			"service setting faithfully. Removing the attribute would not fix a " +
			"server that ignored it, only stop a customer configuring a field the " +
			"API documents.\n\n" +
			"If it is to go, measure the token flow first and say so here.")
	}
}
